    "id": "pf-sfn-logging-destination",
    "service": "stepfunctions",
    "severity": "ERROR",
    "title": "LoggingConfiguration with Level other than OFF needs exactly one Destinations entry carrying CloudWatchLogsLogGroup.LogGroupArn, and a literal ARN must be a CloudWatch Logs log-group ARN ending in :*",
